#pragma once

#include <JuceHeader.h>
#include <juce_cryptography/juce_cryptography.h>
#include <array>
#include "ZLicenseStatus.h"

// RSA signature verification is implemented in a self-contained way using
// JUCE's BigInteger (modular exponentiation) and SHA256. No external crypto
// library (e.g. OpenSSL) is required — the public key is embedded as
// modulus/exponent hex strings (see ZarlinoPublicKey.h generated by CMake).

namespace Zarlino::Licensing {

class ZLicenseKey {
public:
    struct Parsed {
        LicenseInfo info;
        juce::MemoryBlock signature;
        juce::MemoryBlock rawPayload; // binary payload that was signed
    };

    // Parses Base64-encoded license key. Returns false on parse error.
    static bool parseLicenseKey(const juce::String& keyBase64, Parsed& out)
    {
        juce::MemoryBlock decoded;
        if (!decodeBase64ToBinary(keyBase64, decoded))
            return false;

        juce::String err;
        return extractFieldsFromBlob(decoded, out, err);
    }

    // Verifies an RSA-SHA256 (PKCS#1 v1.5) signature using the public key given
    // as modulus/exponent hex strings. Returns true if the signature matches.
    static bool verifySignature(const Parsed& parsed,
                                const juce::String& modulusHex,
                                const juce::String& exponentHex,
                                juce::String& outError)
    {
        juce::BigInteger modulus, exponent;
        modulus.parseString(modulusHex, 16);
        exponent.parseString(exponentHex, 16);

        if (modulus.isZero() || exponent.isZero())
        {
            outError = "Invalid embedded public key";
            return false;
        }

        // keyBytes = byte length of the modulus (256 for a 2048-bit key)
        const int keyBytes = (modulus.getHighestBit() + 8) / 8;
        if (keyBytes <= 0 || parsed.signature.getSize() == 0 || parsed.rawPayload.getSize() == 0)
        {
            outError = "Invalid key or license data";
            return false;
        }

        // Load the signature as a big-endian integer (the blob stores it big-endian)
        const juce::String sigHex = juce::String::toHexString(parsed.signature.getData(),
                                                              (int)parsed.signature.getSize());
        juce::BigInteger signature;
        signature.parseString(sigHex, 16);

        // Recover the EMSA-PKCS1-v1_5 encoded message: m = signature^e mod n
        signature.exponentModulo(exponent, modulus);

        // m as a fixed-width big-endian hex string (2 hex chars per byte)
        const juce::String emHex = signature.toString(16, keyBytes * 2).toLowerCase();

        // SHA-256 of the signed payload
        const juce::SHA256 sha(parsed.rawPayload.getData(), parsed.rawPayload.getSize());
        const juce::String digestHex = sha.toHexString().toLowerCase();

        // Reconstruct the expected PKCS#1 v1.5 block:
        //   00 01 || FF...FF || 00 || DigestInfo(SHA-256)
        // DigestInfo prefix (19 bytes) + 32-byte hash = 51 bytes.
        static constexpr const char* sha256DigestInfoPrefix =
            "3031300d060960864801650304020105000420";
        constexpr int digestInfoBytes = 51;
        const int paddingBytes = keyBytes - 3 - digestInfoBytes;

        if (paddingBytes < 8) // PKCS#1 v1.5 requires at least 8 padding bytes
        {
            outError = "Public key too small for RSA-SHA256";
            return false;
        }

        juce::String expected;
        expected.preallocateBytes((size_t)keyBytes * 2);
        expected << "0001";
        for (int i = 0; i < paddingBytes; ++i)
            expected << "ff";
        expected << "00";
        expected << sha256DigestInfoPrefix;
        expected << digestHex;

        if (expected.equalsIgnoreCase(emHex))
            return true;

        outError = "Signature mismatch";
        return false;
    }

private:
    static bool decodeBase64ToBinary(const juce::String& b64, juce::MemoryBlock& out)
    {
        static const char* lut = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        std::array<int, 256> rev{};
        rev.fill(-1);
        for (int i = 0; i < 64; ++i) rev[(unsigned char)lut[i]] = i;

        juce::String s = b64.trim();
        std::vector<unsigned char> bytes;
        int val = 0, valb = -8;
        for (int i = 0; i < s.length(); ++i)
        {
            unsigned char c = (unsigned char)s[i];
            if (rev[c] == -1) continue;
            val = (val << 6) + rev[c];
            valb += 6;
            if (valb >= 0) {
                bytes.push_back((unsigned char)((val >> valb) & 0xFF));
                valb -= 8;
            }
        }

        if (bytes.empty()) return false;
        out.append(bytes.data(), (size_t)bytes.size());
        return true;
    }

    // Blob format (binary): big-endian uint16 pluginIdLen, pluginId bytes,
    // uint16 emailLen, email bytes, uint16 issueLen, issueDate bytes,
    // uint16 expirationLen, expiration bytes, uint16 sigLen, signature bytes
    static bool extractFieldsFromBlob(const juce::MemoryBlock& blob, Parsed& out, juce::String& outError)
    {
        const auto* data = static_cast<const uint8_t*>(blob.getData());
        size_t total = blob.getSize();
        size_t idx = 0;
        auto readUint16 = [&](uint16_t& v)->bool {
            if (idx + 2 > total) return false;
            v = (uint16_t(data[idx]) << 8) | uint16_t(data[idx + 1]);
            idx += 2;
            return true;
        };
        auto readString = [&](uint16_t len, juce::String& dest)->bool {
            if (idx + len > total) return false;
            dest = juce::String::fromUTF8((const char*)(data + idx), (int)len);
            idx += len;
            return true;
        };

        uint16_t len = 0;
        if (!readUint16(len)) { outError = "Malformed blob (plugin id length)"; return false; }
        if (len == 0) { outError = "Empty plugin id"; return false; }
        if (!readString(len, out.info.pluginId)) { outError = "Malformed blob (plugin id data)"; return false; }

        if (!readUint16(len)) { outError = "Malformed blob (email length)"; return false; }
        if (!readString(len, out.info.licenseeEmail)) { outError = "Malformed blob (email data)"; return false; }

        if (!readUint16(len)) { outError = "Malformed blob (issue date length)"; return false; }
        if (!readString(len, out.info.issueDate)) { outError = "Malformed blob (issue date)"; return false; }

        if (!readUint16(len)) { outError = "Malformed blob (expiration length)"; return false; }
        if (!readString(len, out.info.expirationDate)) { outError = "Malformed blob (expiration)"; return false; }

        uint16_t sigLen = 0;
        if (!readUint16(sigLen)) { outError = "Malformed blob (signature length)"; return false; }
        if (idx + sigLen > total) { outError = "Malformed blob (signature data)"; return false; }

        out.signature.append(data + idx, sigLen);

        // rawPayload is everything from start up to but not including the 2 bytes that encode sigLen
        size_t sigLenFieldOffset = idx - 2;
        if (sigLenFieldOffset > total) sigLenFieldOffset = idx; // fallback
        out.rawPayload.append(data, sigLenFieldOffset);

        return true;
    }
};

} // namespace Zarlino::Licensing
